INSERT OR REPLACE INTO "units" VALUES(1217000100,'高达杰姆纳斯01','高达杰姆纳斯01',2,2,0,0,'10000000021702100','2170','g2170u00100','OZX-GU01A',1,1,1,1,6847,52,716,743,582,4,36559,138,3822,3965,2777,4,67493,241,7057,7320,5093,4,3,1,3,1,2,'于资源卫星殖民地“MO-V”秘密研发的试作型MS一号机。
以设有驾驶舱的本体作为核心组件，该机体通过在各部位搭配适用于不同用途的“G-UNIT”零件，力求在各种环境下都能发挥优异性能。
该机体的基础性能远超量产型MS，同时还配备了加速步枪、光束剑等多种武装。
此外，还搭载了可根据驾驶员的精神状态，在一定时间内提升机体性能的“PX系统”，但发动此系统需要一定的天赋及训练，并且必须依照各个驾驶员调校系统。',NULL,'{"unit_id": 1217000100, "unit_ssp_initial_release_set_id": 1217000100, "unit_ssp_custom_core_group_id": 1217000100, "unit_ssp_add_status_id": 100016, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100016, "ssp_hp": 240, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 4806, "ssp_max_en": 15, "ssp_max_attack": 503, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 121700010001, "unit_ssp_custom_core_group_id": 1217000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700010001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700010001, "weapon_change": {"id": 121700010001, "before_weapon_id": 0, "after_weapon_id": 121700010090}}, {"unit_ssp_custom_core_release_function_set_id": "121700010001", "sort_order": 2, "release_function_type_index": 7, "target_id": 121700010001, "weapon_effect": {"id": 121700010001, "target_weapon_id": 121700010002, "weapon_trait_id": 310010101, "battle_power_rating_point_rate_percent": 5}}]}, {"id": 121700010002, "unit_ssp_custom_core_group_id": 1217000100, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700010002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700010002", "sort_order": 1, "release_function_type_index": 1, "target_id": 121700010002, "weapon_enhance": {"id": 121700010002, "target_weapon_id": 121700010002, "sort_order": 2, 