INSERT OR REPLACE INTO "units" VALUES(1217000200,'高达杰姆纳斯01(突击推进器装备)','高达杰姆纳斯01(突击推进器装备)',3,3,0,0,'10000000021702100','2170','g2170u00200','OZX-GU01A',1,1,1,1,6670,70,738,662,739,5,39753,189,4394,3945,4196,5,61059,279,6749,6060,6435,5,3,1,3,1,2,'杰姆纳斯01装备宇宙用推进器组件的型态。
于肩部、脚部及背部加装推进器，大幅提升在宇宙中的机动性。
开发初期以杰姆纳斯称呼此机体，但是测试驾驶员安迪·班奈特赋予其“为了自由及殖民地而战的高达”的含意，而被命名为“高达杰姆纳斯”。',NULL,'{"unit_id": 1217000200, "unit_ssp_initial_release_set_id": 1217000200, "unit_ssp_custom_core_group_id": 1217000200, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 121700020001, "unit_ssp_custom_core_group_id": 1217000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700020001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700020001, "weapon_change": {"id": 121700020001, "before_weapon_id": 0, "after_weapon_id": 121700020090}}, {"unit_ssp_custom_core_release_function_set_id": "121700020001", "sort_order": 2, "release_function_type_index": 1, "target_id": 121700020001, "weapon_enhance": {"id": 121700020001, "target_weapon_id": 121700020002, "sort_order": 2, "weapon_enhance_type_index": 1, "effect_value": 175}}]}, {"id": 121700020002, "unit_ssp_custom_core_group_id": 1217000200, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700020002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700020002", "sort_order": 1, "release_function_type_index": 1, "target_id": 121700020002, "weapon_enhance": {"id": 121700020002, "target_weapon_id": 121700020002, "sort_order": 2, "weapon_enha