INSERT OR REPLACE INTO "units" VALUES(1217000600,'海德拉高达','海德拉高达',4,3,0,0,'10000000021702100','2170','g2170u00600','OZ-15AGX',1,1,1,1,7963,81,843,717,846,5,52393,235,5545,4713,5305,5,63779,281,6751,5738,6453,5,3,3,3,1,2,'为了对抗宇宙殖民地独立组织开发的五架高达，由OZ开发的高性能试作MS。
但是也有传言说实际上的假想敌是艾比安高达。
具备将双脚收纳后下半身整体变成推进系统的简易变形构造，在宇宙空间的机动性凌驾其他机体之上。
此外，更搭载「精神感应系统」，将驾驶员的神经与传感器群连结，进而掌握周遭空间的状况，并能仅凭意识便可朝目标攻击。
主武装为装备在肩部的强力破坏加农，格斗战时则可从背部展开肩部钩爪。
肩部钩爪还可以与本体分离，以有线操作的方式进行远距离攻击。',NULL,'{"unit_id": 1217000600, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1217000600, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}, "cores": [{"id": 121700060001, "unit_ssp_custom_core_group_id": 1217000600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700060001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700060001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700060001, "weapon_change": {"id": 121700060001, "before_weapon_id": 0, "after_weapon_id": 121700060090}}, {"unit_ssp_custom_core_release_function_set_id": "121700060001", "sort_order": 2, "release_function_type_index": 7, "target_id": 121700060001, "weapon_effect": {"id": 121700060001, "target_weapon_id": 121700060002, "weapon_trait_id": 320290501, "battle_power_rating_point_rate_percent": 5}}]}, {"id": 121700060002, "unit_ssp_custom_core_group_id": 1217000600, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700060002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700060002", "sort_order": 1, "release_function_type_index": 1, "target_id": 121700060002, "weapon_enhance": {"id": 121700060002, "target_weapon_id": 121700060004, "sort_order": 4, "weapon_enhance_type_index": 4, "effect_value": 1}}]}, {"id": 121700060003, "unit_ssp_custom_core_group_id": 1217000600, "level": 10, "release_point": 10000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700060003, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 121700060001, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700060003", "sort_order": 1, "release_function_type_index": 7, "target_id": 121700060003, "weapon_effect": {"id": 121700060003, "target_weapon_id": 121700060090, "weapon_trait_id": 320060501, "battle_power_rating_point_rate_percent": 5}}, {"unit_ssp_custom_core_release_function_set_id": "121700060003", "sort_order": 2, "release_function_type_index": 1, "target_id": 121700060003, "weapon_enhance": {"id": 121700060003, "target_weapon_id": 121700060002, "sort_order": 2, "weapon_enhance_type_index": 1, "effect_value": 400}}]}, {"id": 121700060004, "unit_ssp_custom_core_group_id": 1217000600, "level": 15, "release_point": 3000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700060004, "display_icon_type_index": 2, "schedule_id": 9999990001, "release_condition_custom_core_id": 0, "releases": []}, {"id": 121700060005, "unit_ssp_custom_core_group_id": 1217000600, "level": 20, "release_point": 15000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700060005, "display_icon_type_index": 1, "schedule_id": 9999990001, "release_condition_custom_core_id": 121700060003, "releases": []}]}','海德拉高达','master',1794971433,'v2026.11.18',1217000400,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217000700,'D模组','D模组',1,1,0,0,'10000000021702100','2170','g2170u00700','-',1,1,1,1,5411,61,685,571,601,4,25539,133,3233,2692,2833,4,57788,268,7316,6092,6411,4,3,1,1,1,1,'MO-V开发的无人MS。
为了保卫MO-V，以OZ的MD的资料为基础，将里奥改装而成的机体。
机体用途限定在宇宙战及保卫据点，脚部装上大型推进器，腕部则改装光束加农，并将不需要的零件全数排除。
生产费用低廉但战斗能力却很高，面对以比尔哥Ⅱ为主力的敌方部队也能相抗衡。',NULL,'{"unit_id": 1217000700, "unit_ssp_initial_release_set_id": 1217000700, "unit_ssp_custom_core_group_id": 1217000700, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}, "cores": [{"id": 121700070001, "unit_ssp_custom_core_group_id": 1217000700, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700070001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700070001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700070001, "weapon_change": {"id": 121700070001, "before_weapon_id": 0, "after_weapon_id": 121700070090}}, {"unit_ssp_custom_core_release_function_set_id": "121700070001", "sort_order": 2, "release_function_type_index": 7, "target_id": 121700070001, "weapon_effect": {"id": 121700070001, "target_weapon_id": 121700070001, "weapon_trait_id": 310200101, "battle_power_rating_point_rate_percent": 5}}]}, {"id": 121700070002, "unit_ssp_custom_core_group_id": 1217000700, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700070002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700070002", "sort_order": 1, "release_function_type_index": 1, "target_id": 121700070002, "weapon_enhance": {"id": 121700070002, "target_weapon_id": 121700070001, "sort_order": 1, "weapon_enhance_type_index": 4, "eff