INSERT OR REPLACE INTO "units" VALUES(1217000800,'里奥(MO-V宇宙式样)','里奥(MO-V宇宙式样)',1,1,0,0,'10000000021702100','2170','g2170u00800','OZ-06MS',1,1,1,1,5967,61,690,569,537,4,28164,122,3256,2683,2791,4,63728,242,7369,6071,6370,4,3,1,2,1,2,'隶属于MO-V的里奥宇宙战式样机。
里奥作为联合军的主力MS，在各地区都有配置，在MO-V也运用于殖民地的防卫上。
胸前涂有代表所属的「MO-V」字样，但性能与一般的里奥无异。
在MO-V遭到OZ普莱斯攻击时进行迎击，但由于驾驶员经验不足，面对敌方的杜拉士队陷入了苦战。',NULL,'{"unit_id": 1217000800, "unit_ssp_initial_release_set_id": 1217000800, "unit_ssp_custom_core_group_id": 1217000800, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 121700080001, "unit_ssp_custom_core_group_id": 1217000800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700080001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700080001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700080001, "weapon_change": {"id": 121700080001, "before_weapon_id": 0, "after_weapon_id": 121700080090}}, {"unit_ssp_custom_core_release_function_set_id": "121700080001", "sort_order": 2, "release_function_type_index": 7, "target_id": 121700080001, "weapon_effect": {"id": 121700080001, "target_weapon_id": 121700080001, "weapon_trait_id": 310160101, "battle_power_rating_point_rate_percent": 5}}]}, {"id": 121700080002, "unit_ssp_custom_core_group_id": 1217000800, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700080002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700080002", "sort_order": 1, "release_function_type_index": 3, "target_id": 121700080002, "status_up": {"id": 121700080002, "unit_status_type_index": 6, "effect_value": 1}}]}, {"id": 121700080003, "unit_ssp_custom_core_group_id": 1217000800, "level": 10, "release_point": 10000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700080003, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 121700080001, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700080003", "sort_order": 1, "release_function_type_index": 7, "target_id": 121700080003, "weapon_effect": {"id": 121700080003, "target_weapon_id": 121700080090, "weapon_trait_id": 320210301, "battle_power_rating_point_rate_percent": 5}}, {"unit_ssp_custom_core_release_function_set_id": "121700080003", "sort_order": 2, "release_function_type_index": 1, "target_id": 121700080003, "weapon_enhance": {"id": 121700080003, "target_weapon_id": 121700080001, "sort_order": 1, "weapon_enhance_type_index": 1, "effect_value": 350}}]}, {"id": 121700080004, "unit_ssp_custom_core_group_id": 1217000800, "level": 15, "release_point": 3000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700080004, "display_icon_type_index": 2, "schedule_id": 9999990001, "release_condition_custom_core_id": 0, "releases": []}, {"id": 121700080005, "unit_ssp_custom_core_group_id": 1217000800, "level": 20, "release_point": 15000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700080005, "display_icon_type_index": 1, "schedule_id": 9999990001, "release_condition_custom_core_id": 121700080003, "releases": []}], "initial_release": {"sort_order": 1, "release_function_type_index": 6, "target_id": 121700080001, "ability_change": {"id": 121700080001, "before_ability_id": 0, "after_ability_id": 1000302}, "id": 1217000800}}','里奥(MO-V宇宙式样)','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217000900,'EWAC里奥','EWAC里奥',1,3,0,0,'10000000021702100','2170','g2170u00900','OZ-06MS-E2',1,1,1,1,6041,61,572,595,625,4,28510,138,2696,2807,2821,4,64510,281,6100,6352,6356,4,3,1,2,1,2,'隶属于OZ普莱斯的里奥侦查式样机型。
强化侦查、通信能力，头部装备巨大圆盘型雷达，并搭载多架摄影镜头。
