INSERT OR REPLACE INTO "units" VALUES(1217001400,'雷欧斯','雷欧斯',3,1,0,0,'10000000021702100','2170','g2170u01400','OZ-06MS-SS1',1,1,1,1,6961,71,812,597,697,4,41486,183,4835,3553,4149,4,63722,268,7426,5457,6374,4,3,1,3,1,2,'隶属于OZ普莱斯的里奥特装机。
将里奥改装，作为罗杰·那多纳的专用机，提升整体性能。
武装虽然采标准配备，但不论射击战或格斗战都能应付，是平衡性很好的机体。
或许是驾驶员罗杰个人的喜好，双肩披上披风为其特征。
虽然也有用在进攻MO-V，但面对高达机型的对手，性能稍显不足。',NULL,'{"unit_id": 1217001400, "unit_ssp_initial_release_set_id": 1217001400, "unit_ssp_custom_core_group_id": 1217001400, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}, "cores": [{"id": 121700140001, "unit_ssp_custom_core_group_id": 1217001400, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700140001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700140001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700140001, "weapon_change": {"id": 121700140001, "before_weapon_id": 0, "after_weapon_id": 121700140090}}, {"unit_ssp_custom_core_release_function_set_id": "121700140001", "sort_order": 2, "release_function_type_index": 1, "target_id": 121700140001, "weapon_enhance": {"id": 121700140001, "target_weapon_id": 121700140001, "sort_order": 1, "weapon_enhance_type_index": 1, "effect_value": 175}}]}, {"id": 121700140002, "unit_ssp_custom_core_group_id": 1217001400, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700140002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700140002", "sort_order": 1, "release_function_type_index": 3, "target_id": 121700140002, "status_up": {"id": 121700140002, "unit_status_type_index": 6, "effect_value": 1}}]}, {"id": 121700140003, "unit_ssp_custom_core_group_