虽然也有用在进攻MO-V，但面对高达机型的对手，性能稍显不足。',NULL,'{"unit_id": 1217001500, "unit_ssp_initial_release_set_id": 1217001500, "unit_ssp_custom_core_group_id": 1217001500, "unit_ssp_add_status_id": 100015, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100015, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 15, "ssp_max_attack": 503, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 121700150001, "unit_ssp_custom_core_group_id": 1217001500, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700150001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700150001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700150001, "weapon_change": {"id": 121700150001, "before_weapon_id": 0, "after_weapon_id": 121700150090}}, {"unit_ssp_custom_core_release_function_set_id": "121700150001", "sort_order": 2, "release_function_type_index": 1, "target_id": 121700150001, "weapon_enhance": {"id": 121700150001, "target_weapon_id": 121700150001, "sort_order": 1, "weapon_enhance_type_index": 1, "effect_value": 175}}]}, {"id": 121700150002, "unit_ssp_custom_core_group_id": 1217001500, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700150002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700150002", "sort_order": 1, "release_function_type_index": 3, "target_id": 121700150002, "status_up": {"id": 121700150002, "unit_status_type_index": 6, "effect_value": 1}}]}, {"id": 121700150003, "unit_ssp_custom_core_group_