INSERT OR REPLACE INTO "units" VALUES(1217001600,'高达亚斯克雷普欧斯','高达亚斯克雷普欧斯',3,1,0,0,'10000000021702100','2170','g2170u01600','OZ-10VMSX',1,1,1,1,6993,71,800,669,633,5,41678,166,4763,3985,4177,5,64016,242,7316,6122,6437,5,3,1,3,1,3,'OZ普莱斯将捕获到的高达杰姆纳斯02装备上追加装甲及强化零件而成的机体。
具备可变成接近战模式的变形构造，各种战场都能发挥高性能。
原机的「PX系统」也有保留下来，总和上攻击力更胜高达杰姆纳斯。
除了光束剑、急速射击等基本武器之外，近战模式还可使用特殊兵器「巨蛇钩爪」。',NULL,'{"unit_id": 1217001600, "unit_ssp_initial_release_set_id": 1217001600, "unit_ssp_custom_core_group_id": 1217001600, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 121700160001, "unit_ssp_custom_core_group_id": 1217001600, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700160001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700160001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700160001, "weapon_change": {"id": 121700160001, "before_weapon_id": 0, "after_weapon_id": 121700160090}}, {"unit_ssp_custom_core_release_function_set_id": "121700160001", "sort_order": 2, "release_function_type_index": 1, "target_id": 121700160001, "weapon_enhance": {"id": 121700160001, "target_weapon_id": 121700160004, "sort_order": 4, "weapon_enhance_type_index": 1, "effect_value": 200}}]}, {"id": 121700160002, "unit_ssp_custom_core_group_id": 1217001600, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700160002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700160002", "sort_order": 1, "release_function_type_index": 3, "target_id": 121700160002, "status_up": {"id": 121700160002, "unit_status_type_index": 6, "effect_value": 1}}]}, {"id": 121700160003, "unit_ssp_custom_core_