INSERT OR REPLACE INTO "units" VALUES(1217001710,'高达亚斯克雷普欧斯(PX模式)','高达亚斯克雷普欧斯(PX模式)',4,3,0,0,'10000000021702100','2170','g2170u01700','OZ-10VMSX',1,1,1,1,8431,89,919,829,929,5,55471,260,6045,5453,5821,5,61388,282,6691,6035,6437,5,3,1,3,1,3,'OZ普莱斯的高机动强袭型MS。
本机是在掳获而来的高达杰姆纳斯02上，加装了追加装甲与强化零件而成的机体，
并具备可切换为近身战模式的变形结构，因此在各种战场上都能发挥出优异的性能。
除了光束剑、急速射击等一般武装外，在近身战模式下还可使用特殊兵器“巨蛇钩爪”。
此外，杰姆纳斯02所搭载的“PX系统”也被完整保留下来，在综合攻击力方面甚至凌驾于高达杰姆纳斯之上。',NULL,'{"unit_id": 1217001710, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1217001710, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}, "cores": [{"id": 121700171001, "unit_ssp_custom_core_group_id": 1217001710, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700171001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700171001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700171001, "weapon_change": {"id": 121700171001, "before_weapon_id": 0, "after_weapon_id": 121700171090}}, {"unit_ssp_custom_core_release_function_set_id": "121700171001", "sort_order": 2, "release_function_type_index": 7, "target_id": 121700171001, "weapon_effect": {"id": 121700171001, "target_weapon_id": 121700171002, "weapon_trait_id": 320270501, "battle_power_rating_point_rate_percent": 5}}]}, {"id": 121700171002, "unit_ssp_custom_core_group_id": 1217001710, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700171002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700171002", "sort_order": 1, "release_function_type_index": 1, "target_id": 121700171002, "weapon_enhance": {"id": 121700171002, "target_weapon_id": 121700171002, "sort_order": 2, "weapon_enhance_type_index": 4,