INSERT OR REPLACE INTO "units" VALUES(1217001900,'音速高达L.O.','音速高达L.O.',4,2,0,0,'10000000021702100','2170','g2170u01900','OZX-GU01LOB',1,1,1,1,8387,68,877,928,682,5,55184,190,5767,6103,4483,5,67177,227,7020,7431,5458,5,3,3,3,1,2,'高达杰姆纳斯01装备了高机动强化组件“03LOB系统”的型态。
通过组件系统内藏的发电机及推进器，输出和推力均提升至两倍以上。
也能通过简易变形，切换成高速飞行模式。
此外，为了辅助高速机动而装备了大型雷达，侦查能力也有提升。
主武装改成“轻量型加速冲锋枪”，也能利用内藏在双肩的反应式组件中的“推进光束加农”进行长距离炮击。',NULL,'{"unit_id": 1217001900, "unit_ssp_initial_release_set_id": 1217001900, "unit_ssp_custom_core_group_id": 1217001900, "unit_ssp_add_status_id": 100018, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100018, "ssp_hp": 240, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 26, "ssp_mobility": 19, "ssp_max_hp": 4806, "ssp_max_en": 16, "ssp_max_attack": 503, "ssp_max_defense": 526, "ssp_max_mobility": 389}, "cores": [{"id": 121700190001, "unit_ssp_custom_core_group_id": 1217001900, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700190001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700190001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700190001, "weapon_change": {"id": 121700190001, "before_weapon_id": 0, "after_weapon_id": 121700190090}}, {"unit_ssp_custom_core_release_function_set_id": "121700190001", "sort_order": 2, "release_function_type_index": 7, "target_id": 121700190001, "weapon_effect": {"id": 121700190001, "target_weapon_id": 121700190003, "weapon_trait_id": 320030501, "battle_power_rating_point_rate_percent": 5}}]}, {"id": 121700190002, "unit_ssp_custom_core_group_id": 1217001900, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700190002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700190002", "sort_order": 1, "release_function_type_index": 3, "target_id": 121700190002, "status_up": {"id": 121700190002, "unit_status_type_index": 6, "effect_value": 1}}]}, {"id": 121700190003, "unit_