INSERT OR REPLACE INTO "units" VALUES(1217002100,'幻象高达','幻象高达',4,1,0,0,'10000000021702100','2170','g2170u02100','OZ-19MASX',1,1,1,1,8050,81,924,761,715,5,52967,203,6073,5003,5214,5,64478,241,7394,6091,6357,5,3,3,3,1,2,'以OZ的试作型可变MS为基础，欧帝·班奈特秘密制造的机体。
攻击力、防御力及机动力全都经过优化的超高性能MS。
透过变形成MA型态、中间型态 (突击模式)，在各种环境下都能进行高机动战斗，输出更是高达杰姆纳斯的3倍以上。
此外，藉由搭载的「MSCS (精神同步型操纵系统)」，与驾驶员精神联接后能够自由自在地控制机体，减轻高机动时的操纵负荷。
装备了「光束矛」及「超绝MEGA粒子巨炮」等非常强力的武器，MA型态时也能发射破坏MEGA粒子炮。
双肩也装备了能使光束兵器无效化的「反射护罩」。',NULL,'{"unit_id": 1217002100, "unit_ssp_initial_release_set_id": 1217002100, "unit_ssp_custom_core_group_id": 1217002100, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}, "cores": [{"id": 121700210001, "unit_ssp_custom_core_group_id": 1217002100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700210001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700210001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700210001, "weapon_change": {"id": 121700210001, "before_weapon_id": 0, "after_weapon_id": 121700210090}}, {"unit_ssp_custom_core_release_function_set_id": "121700210001", "sort_order": 2, "release_function_type_index": 7, "target_id": 121700210001, "weapon_effect": {"id": 121700210001, "target_weapon_id": 121700210003, "weapon_trait_id": 320390201, "battle_power_rating_point_rate_percent": 5}}]}, {"id": 121700210002, "unit_ssp_custom_core_group_id": 1217002100, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700210002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700210002", "sort_order": 1, "release_function_type_index": 3, "target_id": 121700210002, "status_up": {"id": 121700210002, "unit_status_type_index": 6, "effect_value": 1}}]}, {"id": 121700210003, "unit_ssp_custom_core_group_id":