INSERT OR REPLACE INTO "units" VALUES(1217002300,'高达班雷普欧斯','高达班雷普欧斯',4,2,0,0,'10000000021702100','2170','g2170u02300','OZ-10VMSX-2',1,1,1,1,8422,64,874,921,727,5,55416,200,5746,6059,4255,5,67459,240,6996,7376,5170,5,3,1,3,1,3,'将OZ普莱斯的高达亚斯克雷普欧斯加以改装的机体。
虽然外型上没有太大的差异，性能方面却有全面性的提升，并追加装备大型实体剑。
此外，仍保留原机的「PX系统」，具备高性能的同时，操作上也有难度。
葛兰夏丽欧攻防战时，由克拉兹·谢尔维搭乘，迎击MO-V高达部队。',NULL,'{"unit_id": 1217002300, "unit_ssp_initial_release_set_id": 1217002300, "unit_ssp_custom_core_group_id": 1217002300, "unit_ssp_add_status_id": 100016, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100016, "ssp_hp": 240, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 4806, "ssp_max_en": 15, "ssp_max_attack": 503, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 121700230001, "unit_ssp_custom_core_group_id": 1217002300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700230001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700230001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700230001, "weapon_change": {"id": 121700230001, "before_weapon_id": 0, "after_weapon_id": 121700230090}}, {"unit_ssp_custom_core_release_function_set_id": "121700230001", "sort_order": 2, "release_function_type_index": 1, "target_id": 121700230001, "weapon_enhance": {"id": 121700230001, "target_weapon_id": 121700230004, "sort_order": 4, "weapon_enhance_type_index": 1, "effect_value": 200}}]}, {"id": 121700230002, "unit_ssp_custom_core_group_id": 1217002300, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700230002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700230002", "sort_order": 1, "release_function_type_index": 3, "target_id": 121700230002, "status_up": {"id": 121700230002, "unit_status_type_index": 6, "effect_value": 1}}]}, {"id": 121700230003, "unit_ssp_custom_core_group