INSERT OR REPLACE INTO "units" VALUES(1217002410,'高达班雷普欧斯(PX模式)','高达班雷普欧斯(PX模式)',4,1,0,0,'10000000021702100','2170','g2170u02400','OZ-10VMSX-2',1,1,1,1,8411,88,1060,792,836,5,55339,233,6970,5211,5785,5,61242,253,7713,5767,6407,5,3,1,3,1,3,'OZ普莱斯的高机动强袭型MS。
这架机体是由高达亚斯克雷普欧斯进一步改装而成的强化机体，整体性能也获得全面提升。
此外，“PX系统”也完整承袭自原机，虽然性能优异，却是一架相当难以驾驭的机体。
在葛兰夏丽欧攻防战中，曾迎击MO-V的高达部队，最后却因PX系统超载而自毁。',NULL,'{"unit_id": 1217002410, "unit_ssp_initial_release_set_id": 1217002410, "unit_ssp_custom_core_group_id": 1217002410, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}, "cores": [{"id": 121700241001, "unit_ssp_custom_core_group_id": 1217002410, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 121700241001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700241001", "sort_order": 1, "release_function_type_index": 5, "target_id": 121700241001, "weapon_change": {"id": 121700241001, "before_weapon_id": 0, "after_weapon_id": 121700241090}}, {"unit_ssp_custom_core_release_function_set_id": "121700241001", "sort_order": 2, "release_function_type_index": 7, "target_id": 121700241001, "weapon_effect": {"id": 121700241001, "target_weapon_id": 121700241002, "weapon_trait_id": 320210201, "battle_power_rating_point_rate_percent": 5}}]}, {"id": 121700241002, "unit_ssp_custom_core_group_id": 1217002410, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000021002170, "unit_ssp_custom_core_release_function_set_id": 121700241002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "121700241002", "sort_order": 1, "release_function_type_index": 3, "target_id": 121700241002, "status_up": {"id": 121700241002, "unit_status_type_index": 6, "effect_value": 1}}]}, {"id": 121700241003, "unit_ssp_custom_