INSERT OR REPLACE INTO "units" VALUES(1510000100,'高达吉利乌斯','高达吉利乌斯',4,2,0,0,'10000000000005100','5100','g5100u00100','EES-001',1,1,1,1,8820,69,898,851,684,5,58030,191,5907,5594,4495,5,70642,228,7191,6810,5472,5,3,3,3,1,2,'机体型号：EES-001
为配合国际组织“太阳系同盟”推动的“外太空探测计划”，伊斯特恩德公司开发了这款最新型的舱外活动用MS。
距今两百年前，人类在土星环发现了未知生物的遗骸“天鹅之母”。近年的研究证实，它其实是来自太阳系外的生命体。
人们相信，研究这种能够穿梭星际的生物，将有助于人类发展与突破，因此投入庞大的预算与人力，催生了“外太空探测计划”。
由于外太空对人类而言仍是未知领域，舱外活动用MS必须具备高度泛用性，以应对各种难以预测的突发状况。
数家公司历经长达数年的竞标与测试，最终脱颖而出的正是EES系列。
其开发理念为“实现人类梦想的次世代万能机”。
本机体的最大特色，在于搭载于背部的“羽翼延伸装置”。',NULL,'{"unit_id": 1510000100, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1510000100, "unit_ssp_add_status_id": 100019, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100019, "ssp_hp": 240, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 24, "ssp_mobility": 19, "ssp_max_hp": 4806, "ssp_max_en": 16, "ssp_max_attack": 549, "ssp_max_defense": 481, "ssp_max_mobility": 389}, "cores": [{"id": 151000010001, "unit_ssp_custom_core_group_id": 1510000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 151000010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "151000010001", "sort_order": 1, "release_function_type_index": 5, "target_id": 151000010001, "weapon_change": {"id": 151000010001, "before_weapon_id": 0, "after_weapon_id": 151000010090}}, {"unit_ssp_custom_core_release_function_set_id": "151000010001", "sort_order": 2, "release_function_type_index": 1, "target_id": 151000010001, "weapon_enhance": {"id": 151000010001, "target_weapon_id": 151000010002, "sort_order": 1, "weapon_enhance_type_index": 1, "effect_value": 200}}]}, {"id": 151000010002, "unit_ssp_custom_core_group_id": 1510000100, "level": 5, "release_point": 2000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 151000010002, "display_icon_type_index": 3, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": "151000010002", "sort_order": 1, "release_function_type_index": 1, "target_id": 151000010002, "weapon_enhance": {"id": 151000010002, "target_weapon_id": 151000010003, "sort_order": 1, "weapon_enhance_type_index": 3, "effect_value": 1}}]}, {"id": 151000010003,